-- DRE orçada da Zacarini 2.3.7; Orc_Dados (Ano/Tipo=Projetado).
-- Cálculo: bruta+impostos=líquida; líquida+CMV=lucro bruto; despesas seis grupos;
-- EBITDA=lucro bruto+despesas; lucro líquido=EBITDA+financeiras+outros tributos.
-- Referência gerencial; 'Realizado' do Excel NÃO é replicado como atual.
ON CONFLICT (codigo,competencia) DO UPDATE SET
 grupo=excluded.grupo,rotulo=excluded.rotulo,valor=excluded.valor,
 unidade=excluded.unidade,origem_aba=excluded.origem_aba,origem_celula=excluded.origem_celula,
 versao=excluded.versao WHERE public.compras_dashboard_config_237.situacao='referencia';
